class Cdp{constructor(url){this.socket=new WebSocket(url);this.id=0;this.pending=new Map();}async open(){if(this.socket.readyState!==WebSocket.OPEN)await new Promise((ok,no)=>{this.socket.addEventListener('open',ok,{once:true});this.socket.addEventListener('error',no,{once:true});});this.socket.addEventListener('message',(event)=>{const value=JSON.parse(String(event.data));if(!value.id)return;const pending=this.pending.get(value.id);if(!pending)return;this.pending.delete(value.id);value.error?pending.no(new Error(value.error.message)):pending.ok(value.result);});}send(method,params={}){const id=++this.id;return new Promise((ok,no)=>{this.pending.set(id,{ok,no});this.socket.send(JSON.stringify({id,method,params}));});}async eval(expression){const result=await this.send('Runtime.evaluate',{expression,awaitPromise:true,returnByValue:true});if(result.exceptionDetails)throw new Error(result.exceptionDetails.text);return result.result.value;}close(){this.socket.close();}}
async function freePort(){const server=createServer();await new Promise((ok,no)=>{server.once('error',no);server.listen(0,'127.0.0.1',ok);});const value=server.address().port;await new Promise((ok)=>server.close(ok));return value;}
async function launch(){port=await freePort();const env={...process.env,APPDATA:path.join(dataRoot,'roaming'),LOCALAPPDATA:dataRoot,FIELORA_E2E:'1',FIELORA_E2E_DEBUG_PORT:String(port),FIELORA_E2E_ATTACHMENT_PATHS:JSON.stringify([attachmentPath]),ELECTRON_MIRROR:'https://npmmirror.com/mirrors/electron/'};const launched=launchDesktop(root, appPath, packaged, env);launched.stdout.on('data',(chunk)=>output.push(String(chunk)));launched.stderr.on('data',(chunk)=>output.push(String(chunk)));return launched;}
async function connect(){const started=Date.now();while(Date.now()-started<60_000){try{const targets=await(await fetch(`http://127.0.0.1:${port}/json/list`)).json();const target=targets.find((item)=>item.type==='page'&&(item.url.startsWith('fielora://app')||item.url.includes('main_window')));if(target){const cdp=new Cdp(target.webSocketDebuggerUrl);await cdp.open();await cdp.send('Runtime.enable');await cdp.send('Page.enable');return cdp;}}catch{}await new Promise((ok)=>setTimeout(ok,100));}throw new Error(`Electron target timeout\n${output.join('')}`);}
async function wait(cdp,expression,timeout=20_000){const started=Date.now();while(Date.now()-started<timeout){try{if(await cdp.eval(`(async()=>Boolean(await (${expression})))()`))return;}catch{}await new Promise((ok)=>setTimeout(ok,75));}throw new Error(`wait failed: ${expression}\n${output.join('')}`);}
function setValue(selector,value){return`(()=>{const element=document.querySelector(${JSON.stringify(selector)});const descriptor=Object.getOwnPropertyDescriptor(Object.getPrototypeOf(element),'value');descriptor.set.call(element,${JSON.stringify(value)});element.dispatchEvent(new Event('input',{bubbles:true}));return true;})()`;}
async function dragDivider(cdp,testId,delta){const rect=await cdp.eval(`(()=>{const value=document.querySelector('[data-testid=${JSON.stringify(testId)}]').getBoundingClientRect();return{x:value.x,y:value.y,width:value.width,height:value.height};})()`);const x=rect.x+rect.width/2;const y=rect.y+Math.min(120,rect.height/2);await cdp.send('Input.dispatchMouseEvent',{type:'mousePressed',x,y,button:'left',clickCount:1});await cdp.send('Input.dispatchMouseEvent',{type:'mouseMoved',x:x+delta,y,button:'left',buttons:1});await cdp.send('Input.dispatchMouseEvent',{type:'mouseReleased',x:x+delta,y,button:'left',clickCount:1});await new Promise((ok)=>setTimeout(ok,120));}
async function quit(cdp){await cdp.eval('void window.fielora.core.quit()');cdp.close();await Promise.race([new Promise((ok)=>child.once('exit',ok)),new Promise((_,no)=>setTimeout(()=>no(new Error('quit timeout')),10_000))]);}
async function captureProductionAgent(cdp,name){const screenshot=await cdp.send('Page.captureScreenshot',{format:'png'});await writeFile(path.join(productionAgentEvidence,name),Buffer.from(screenshot.data,'base64'));}

